replies := make(chan tagged, len(recipients))
var wg sync.WaitGroup
for _, r := range recipients {
    wg.Add(1)
    go func(r Recipient) { defer wg.Done(); replies <- tagged{r, ask(ctx, r)} }(r)
}
timer := time.NewTimer(budget); defer timer.Stop()
got := make([]Offer, 0, len(recipients))
for len(got) < len(recipients) {
    select {
    case t := <-replies: if t.err == nil { got = append(got, t.offer) }
    case <-timer.C: return merge(got)     // deadline: merge what arrived
    case <-ctx.Done(): return merge(got)
    }
}
